// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceUrlListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceUrlListener = UniffiVTableCallbackInterfaceUrlListener(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeUrlListener.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface UrlListener: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeUrlListener.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface UrlListener: handle missing in uniffiClone")
            }
        },
        onUrl: { (
            uniffiHandle: UInt64,
            url: RustBuffer,
            sessionHex: RustBuffer,
            fileName: RustBuffer,
            fileSize: UInt64,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeUrlListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onUrl(
                     url: try FfiConverterString.lift(url),
                     sessionHex: try FfiConverterString.lift(sessionHex),
                     fileName: try FfiConverterString.lift(fileName),
                     fileSize: try FfiConverterUInt64.lift(fileSize)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceUrlListener> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceUrlListener>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitUrlListener() {
    uniffi_bitmule_mobile_ffi_fn_init_callback_vtable_urllistener(UniffiCallbackInterfaceUrlListener.vtablePtr)
}

