public struct FfiConverterTypeBitmuleError: FfiConverterRustBuffer {
    typealias SwiftType = BitmuleError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BitmuleError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidUrl(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidFragment(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Network(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Transport(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Verify(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Io(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Unknown(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BitmuleError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidUrl(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InvalidFragment(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Network(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Transport(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Verify(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Io(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Unknown(reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


